import re, datetime as dt

def parse(path):
    txt = open(path).read()
    evs = []
    for block in re.findall(r'BEGIN:VEVENT(.*?)END:VEVENT', txt, re.S):
        s = re.search(r'DTSTART:(\d{8}T\d{6}Z)', block)
        e = re.search(r'DTEND:(\d{8}T\d{6}Z)', block)
        if s and e:
            evs.append((dt.datetime.strptime(s.group(1), '%Y%m%dT%H%M%SZ'),
                        dt.datetime.strptime(e.group(1), '%Y%m%dT%H%M%SZ')))
    return evs

cal = {
    'alice': parse('/app/alice_calendar.ics'),
    'bob':   parse('/app/bob_calendar.ics'),
    'carol': parse('/app/carol_calendar.ics'),
}

days = [dt.date(2024, 1, 15) + dt.timedelta(days=i) for i in range(5)]

def T(d, h, m=0):
    return dt.datetime(d.year, d.month, d.day, h, m)

def base_windows(name, d):
    if name == 'alice':
        return [(T(d, 9), T(d, 14))]          # no meetings before 9 or after 14
    if name == 'bob':
        end = T(d, 16, 30) if d.weekday() in (1, 3) else T(d, 17)
        return [(T(d, 10), end)]              # no meetings before 10
    # carol: 9-17 with 12:00-12:30 lunch blocked
    return [(T(d, 9), T(d, 12)), (T(d, 12, 30), T(d, 17))]

def busy(name, d):
    out = []
    for s, e in cal[name]:
        if s.date() == d:
            out.append((s, e))
    if name == 'carol':
        # 15-min buffer after meetings ending 16:45 or later
        out = [(s, e + dt.timedelta(minutes=15) if e.time() >= dt.time(16, 45) else e)
               for s, e in out]
    return out

def free_blocks(name, d):
    blocks = base_windows(name, d)
    for bs, be in busy(name, d):
        nxt = []
        for a, b in blocks:
            if be <= a or bs >= b:
                nxt.append((a, b))
            else:
                if a < bs:
                    nxt.append((a, min(bs, b)))
                if be < b:
                    nxt.append((max(be, a), b))
        blocks = nxt
    return blocks

def slot_ok(name, s, e):
    return any(a <= s and e <= b for a, b in free_blocks(name, s.date()))

LEN = dt.timedelta(minutes=60)
valid = []
for d in days:
    cur = T(d, 9)
    end_of_day = T(d, 18)
    while cur + LEN <= end_of_day:
        e = cur + LEN
        if all(slot_ok(n, cur, e) for n in ('alice', 'bob', 'carol')):
            valid.append((cur, e))
        cur += dt.timedelta(minutes=1)

print("Total valid 1-hour slots:", len(valid))
for s, e in valid[:12]:
    print("  ", s.strftime('%a %Y-%m-%d %H:%M'), "-", e.strftime('%H:%M'), "UTC")

if not valid:
    raise SystemExit("NO VALID SLOT FOUND")

# Earliest, with Carol's Monday-avoidance as a tie-breaker
valid.sort(key=lambda se: (se[0].weekday() == 0, se[0]))
start, end = valid[0]
print("Chosen:", start.strftime('%a %Y-%m-%d %H:%M'), "-", end.strftime('%H:%M'), "UTC")

fmt = lambda x: x.strftime('%Y%m%dT%H%M%SZ')
ics = f"""BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//Team Scheduler//Meeting Planner//EN
CALSCALE:GREGORIAN
METHOD:PUBLISH
BEGIN:VEVENT
UID:team-planning-meeting-20240117@example.com
DTSTAMP:{fmt(dt.datetime(2024,1,1,0,0,0))}
DTSTART:{fmt(start)}
DTEND:{fmt(end)}
SUMMARY:Team Planning Meeting
DESCRIPTION:1-hour planning meeting for Alice, Bob, and Carol. Earliest slot satisfying all availability constraints.
LOCATION:Conference Room A
ATTENDEE:mailto:alice@example.com
ATTENDEE:mailto:bob@example.com
ATTENDEE:mailto:carol@example.com
END:VEVENT
END:VCALENDAR
"""
open('/app/meeting_scheduled.ics', 'w').write(ics)
print("=== /app/meeting_scheduled.ics ===")
print(ics)
PYEOF

